// Забираем входящие данные
const inputData = $input.first().json;

// Если это массив чисел (ID)
if (Array.isArray(inputData)) {
  return inputData.map(id => ({ json: { id: id } }));
} 

// Если это массив объектов n8n ($input.all())
return $input.all().map(item => {
  const val = item.json;
  return {
    json: typeof val === 'object' ? val : { id: val }
  };
});;

// Приводим ответ Hacker News к той же структуре, что у RemoteOK.
const MAX_AGE_DAYS = 7;
const edge = new Date();
edge.setUTCDate(edge.getUTCDate() - MAX_AGE_DAYS);
const cutoff = edge.toISOString().slice(0, 10);

function onlyDate(value) {
  const s = String(value || '');
  return s.length >= 10 ? s.slice(0, 10) : '';
}

const rows = [];
for (const item of $input.all()) {
  const data = item.json;
  const title = String(data.title || '');

  // время у Hacker News приходит в секундах Unix
  const published = data.time ? onlyDate(new Date(data.time * 1000).toISOString()) : '';
  if (!published || published < cutoff) continue;

  // Компания раньше записывалась заглушкой 'HackerNews Post'.
  // В заголовках вида "Truemetrics (YC S23) Is Hiring in Berlin – GTM Lead"
  // название стоит первым, до пометки YC и слов "is hiring".
  let company = '';
  const m = title.match(/^(.+?)\s*(?:\(YC[^)]*\))?\s+(?:is|Is)\s+(?:hiring|Hiring)/);
  if (m) company = m[1].replace(/\s*\(YC[^)]*\)\s*/, '').trim();
  if (!company) company = 'HackerNews';

  let location = '';
  const loc = title.match(/\b(?:in|In)\s+([A-Z][\w .-]+?)(?:\s*[–—-]|$)/);
  if (loc) location = loc[1].trim();

  let position = title;
  const pos = title.match(/(?:is|Is)\s+(?:hiring|Hiring)\s*(?:in\s+[A-Z][\w .-]+?\s*[–—-]\s*)?(.+)$/);
  if (pos && pos[1].trim().length > 2) position = pos[1].trim();

  rows.push({
    json: {
      job_id: data.id,
      date: published,
      source: 'HackerNews',
      company,
      position,
      location,
      tags: '',
      link: data.url || `https://news.ycombinator.com/item?id=${data.id}`,
      description: (data.text || '').replace(/<[^>]*>/g, '').slice(0, 600)
    }
  });
}

console.log('свежих вакансий: ' + rows.length + ', отсечка ' + cutoff);
return rows;

// Складываем обе ветки Hacker News и убираем то, что уже есть в таблице.
// Лента YC-вакансий (jobstories) и тред «Who is hiring» пересекаются редко,
// но job_id из них могут совпасть — сверяем и между собой тоже.
const existing = new Set(
  $('Get row(s) in sheet').all()
    .map(i => String(i.json.job_id ?? '').trim())
    .filter(Boolean)
);

const fromThread = $input.all().map(i => i.json);
let fromFeed = [];
try {
  fromFeed = $('Code in JavaScript1').all().map(i => i.json);
} catch (e) {
  fromFeed = [];   // ветка ленты могла ничего не вернуть
}

const seen = new Set();
const out = [];
for (const row of fromFeed.concat(fromThread)) {
  const id = String(row.job_id ?? '').trim();
  if (!id || existing.has(id) || seen.has(id)) continue;
  seen.add(id);
  out.push({ json: row });
}

console.log('лента: ' + fromFeed.length + ', тред: ' + fromThread.length +
            ', новых к записи: ' + out.length);
return out;

// Из свежих тредов пользователя whoishiring берём именно «Who is hiring?»:
// рядом с ним каждый месяц выходит «Who wants to be hired?» — там резюме, а не вакансии.
const hits = $input.first().json.hits || [];
const thread = hits.find(h => /who is hiring/i.test(h.title || ''));
if (!thread) {
  console.log('свежий тред Who is hiring не найден');
  return [];
}
console.log('тред: ' + thread.title + ' (' + thread.objectID + ')');
return [{ json: { thread_id: thread.objectID, title: thread.title } }];

// Разбор ежемесячного треда «Ask HN: Who is hiring?».
// Каждое объявление — комментарий верхнего уровня в формате
//   Компания | Локация | Тип занятости | Должность | ссылка
// Разделители соблюдают не все, поэтому поля определяются по содержимому,
// а не по номеру позиции.
const MAX_AGE_DAYS = 7;
const edge = new Date();
edge.setUTCDate(edge.getUTCDate() - MAX_AGE_DAYS);
const cutoff = edge.toISOString().slice(0, 10);

const ROLE = /\b(engineer|developer|scientist|manager|designer|analyst|lead|architect|devops|sre|researcher|intern|founding|cto|programmer|consultant|specialist|director|role|position)s?\b/i;
const PLACE = /\b(remote|onsite|on-site|hybrid|san francisco|new york|nyc|london|berlin|austin|seattle|boston|toronto|chicago|denver|amsterdam|paris|bangalore|usa|u\.s\.|uk|eu|europe|canada|india|germany|anywhere|worldwide)\b|[A-Z][a-z]+,\s*[A-Z]{2}\b/;
const JOBTYPE = /\b(full[- ]time|part[- ]time|contract|internship|freelance)\b/i;
// Название должности как таковое: несколько слов с заглавной, оканчивающихся
// ролевым словом. Пересказ вроде «lead investor but also a partner» под шаблон
// не подходит — пустая ячейка честнее обрывка описания.
const TITLE = /\b((?:[A-Z][\w\/&+-]*\s+){0,3}(?:Engineer|Developer|Scientist|Manager|Designer|Analyst|Architect|Researcher|Programmer|Consultant|Specialist|Director)s?)\b/;

function clean(html) {
  let t = String(html || '').replace(/<[^>]+>/g, ' ');
  const map = { '&#x2F;': '/', '&amp;': '&', '&quot;': '"', '&#x27;': "'",
                '&gt;': '>', '&lt;': '<', '&nbsp;': ' ' };
  for (const k of Object.keys(map)) t = t.split(k).join(map[k]);
  return t.replace(/\s+/g, ' ').trim();
}

function tidy(s, limit) {
  let t = String(s || '').replace(/https?:\/\/\S+/g, '').replace(/^[\s\-–—|,]+|[\s\-–—|,]+$/g, '');
  if (t.length > limit) t = t.slice(0, limit).replace(/\s+\S*$/, '');
  const opened = (t.split('(').length - 1) - (t.split(')').length - 1);
  if (opened > 0) t = t.split('(').slice(0, -opened).join('(');
  return t.replace(/^[\s\-–—|,(]+|[\s\-–—|,(]+$/g, '');
}

const thread = $input.first().json;
const kids = (thread.children || []).filter(c => c && c.text);

const rows = [];
for (const c of kids) {
  const published = String(c.created_at || '').slice(0, 10);
  if (!published || published < cutoff) continue;

  const text = clean(c.text);
  const parts = text.split('|').map(p => p.trim()).filter(Boolean);
  if (parts.length < 2) continue;   // объявление без разделителей — не разобрать

  const company = tidy(parts[0].replace(/\s*\([^)]*\)\s*$/, ''), 50);
  if (!company || company.length > 50) continue;

  const labels = parts.slice(1).filter(p => p.length <= 110);

  let position = '';
  for (const p of labels) {
    if (ROLE.test(p) && !JOBTYPE.test(p.trim())) { position = tidy(p, 80); break; }
  }
  if (!position) {
    const m = text.match(TITLE);
    position = m ? tidy(m[1], 60) : '';
  }

  let location = '';
  for (const p of labels) {
    if (p !== position && PLACE.test(p)) { location = tidy(p, 50); break; }
  }

  const jobtype = (labels.find(p => JOBTYPE.test(p)) || '').slice(0, 30);

  rows.push({ json: {
    job_id: c.id,
    date: published,
    source: 'HackerNews',
    company,
    position,
    location,
    tags: jobtype,
    link: 'https://news.ycombinator.com/item?id=' + c.id,
    description: text.slice(0, 600),
  }});
}

console.log('из треда «' + (thread.title || '') + '»: ' + rows.length + ' вакансий, отсечка ' + cutoff);
return rows;
